CREATE TABLE `law_gabon` (
  `id` int NOT NULL AUTO_INCREMENT,
  `category` varchar(100) DEFAULT NULL,
  `article_section_no` varchar(255) DEFAULT NULL,
  `title` text,
  `description` longtext,
  `part_chapter` varchar(255) DEFAULT NULL,
